INSERT INTO solutions (id, category, title, slug, summary, body, video_url, template_type, template_value, implementation_scope, status, setup_step) VALUES ('sol_es_role_account', 'exec_secretary', 'Create the ward''s role account', 'role-account', 'Make one shared Google account for the calling, not for a person, so it can pass to the next Executive Secretary.', '## Done when' || char(10) || '' || char(10) || '- A shared Google account for the calling (not a person).' || char(10) || '- 2-step verification is on.' || char(10) || '- Recovery details the next Executive Secretary can take over.' || char(10) || '- The zippa.run access request is sent (send it as soon as the account exists).' || char(10) || '' || char(10) || 'Full how-to coming soon.', NULL, NULL, NULL, 'ward_singleton', 'published', 1) ON CONFLICT(id) DO UPDATE SET category = excluded.category, title = excluded.title, slug = excluded.slug, summary = excluded.summary, body = excluded.body, video_url = excluded.video_url, template_type = excluded.template_type, template_value = excluded.template_value, implementation_scope = excluded.implementation_scope, status = excluded.status, setup_step = excluded.setup_step, updated_at = datetime('now');
INSERT INTO solutions (id, category, title, slug, summary, body, video_url, template_type, template_value, implementation_scope, status, setup_step) VALUES ('sol_es_wardforward_setup', 'exec_secretary', 'Set up WardForward: callings and spaces', 'wardforward-setup', 'Invite the bishopric and ward council with their callings and give each organization''s leaders their space.', '## Done when' || char(10) || '' || char(10) || '- The bishop approved the ward using WardForward (General Handbook 38.8.21.2).' || char(10) || '- The bishop and the Executive Secretary are ward admins, so the ward has at least two administrators.' || char(10) || '- The bishopric and ward council are invited with their callings.' || char(10) || '- Each organization''s president and secretary own their organization''s space.' || char(10) || '- The Ward Clerk is in the Bishopric space.' || char(10) || '- An Activities chair or Ward Mission Leader outside the Ward Council space sees only their own organization''s posts until they are added.' || char(10) || '' || char(10) || 'Full how-to coming soon.', NULL, NULL, NULL, 'ward_singleton', 'published', 2) ON CONFLICT(id) DO UPDATE SET category = excluded.category, title = excluded.title, slug = excluded.slug, summary = excluded.summary, body = excluded.body, video_url = excluded.video_url, template_type = excluded.template_type, template_value = excluded.template_value, implementation_scope = excluded.implementation_scope, status = excluded.status, setup_step = excluded.setup_step, updated_at = datetime('now');
